  def caveats
    <<~EOS
      dev-domains installs caddy automatically via Homebrew dependencies.

      Important paths:
        #{opt_pkgshare}/caddy/Caddyfile
        #{opt_pkgshare}/caddy/apps
        #{opt_pkgshare}/docs

      First-time setup:
        dev-domains setup

      That command will:
        - start or restart caddy
        - use nip.io hostnames like http://flux.127.0.0.1.nip.io

      No dnsmasq or /etc/resolver setup is required.
    EOS
  end

  test do
